mapper.delete:
DELETE
FROM scx_ocpx_flow_log_detail
WHERE expires_at<NOW(3) LIMIT #{limit}

mapper.select:
SELECT id, event_time FROM scx_ocpx_flow_log FORCE INDEX (idx_ocpx_flow_log_preview_retention) WHERE response_preview_present=1 AND response_preview IS NOT NULL AND event_time<DATE_SUB(NOW(3), INTERVAL 7 DAY)
AND (event_time>#{eventTime} OR (event_time=#{eventTime} AND id>#{id}))
ORDER BY event_time, id LIMIT #{limit}
